from pathlib import Path

path = Path('03-enterprise/prototype-v4/index.html')
text = path.read_text()
replacements = {
    '一个后台，管理所有合作客户的发行业务': '统一管理合作客户的发行业务',
    '为厂牌、版权方、音乐人等合作客户建立独立业务空间，统一管理账号、曲库、发行、数据与结算关系。每个客户保留清晰的数据与权限边界，运营团队则可跨客户集中处理日常业务，支撑从几十到上千客户的规模化发行运营。': '为厂牌、版权方、音乐人等合作客户建立独立业务空间，统一管理账号、曲库、发行、数据与结算。各客户保持清晰的数据与权限边界，支持多客户规模化运营。',
    '从客户入驻到持续发行与结算，完整保留每个客户的业务上下文。': '客户、内容、发行与结算关系保持清晰，便于持续运营。',
    '统一管理从艺人到歌曲的完整音乐目录': '统一管理艺人、专辑与歌曲',
    '以艺人、发行、专辑和歌曲为核心组织音乐内容，将音频、封面、ISRC / UPC、版权信息与发行元数据关联到同一内容记录。支持搜索、筛选、批量处理与历史追踪，让内容从导入、编辑、发行到后续更新始终保持完整和可追溯。': '集中管理艺人、专辑、歌曲及其音频、封面、版权信息、ISRC / UPC 和发行元数据。支持搜索、筛选、批量处理与历史追踪，保持内容资料完整并可持续更新。'
}
for old, new in replacements.items():
    if old not in text:
        raise SystemExit(f'missing target: {old}')
    text = text.replace(old, new, 1)
path.write_text(text)
